  function renderHeader() {
    const user = currentUser();
    $('.audience-tabs').hidden = Boolean(user);
    $$('.audience-tab').forEach((tab) => { tab.classList.toggle('is-active', tab.dataset.audience === data.audience); tab.setAttribute('aria-pressed', String(tab.dataset.audience === data.audience)); });
    const scenarioPicker = $('#demo-scenario'); const missionPicker = $('#demo-mission-scenario'); const modeToggle = $('#demo-scenario-mode');
    if (modeToggle) modeToggle.checked = data.scenarioPickerEnabled !== false;
    if (scenarioPicker) scenarioPicker.hidden = data.scenarioPickerEnabled === false;
    if (missionPicker) { missionPicker.hidden = data.scenarioPickerEnabled !== false; missionPicker.value = data.selectedMission || 'C1'; }
    if (scenarioPicker) scenarioPicker.value = data.scenario;
    let nav = ''; let actions = '';
    if (!user) {
      nav = navButtons([['home', 'Cómo funciona']]);
      actions = '<button class="button button-ghost" type="button" data-action="login">Entrar o registrarse</button>';
    } else if (user.role === 'account') {
      actions = accountMenu('CU', user.name, 'Cuenta autenticada · perfil incompleto', '', '');
    } else if (user.role === 'client') {
      nav = navButtons([['client-dashboard', 'Mis anuncios'], ['publish', 'Publicar anuncio'], ['client-profile', 'Mi perfil']]); actions = accountMenu('MR', user.name, `Cliente · ${user.id}`, data.session.hasCarrier ? 'Ir al panel Transportista' : 'Trabajar como transportista', 'carrier');
    } else if (user.role === 'carrier') {
      nav = navButtons([['search', 'Buscar anuncios'], ['carrier-quotes', 'Mis presupuestos'], ['membership', 'Membresía y facturación'], ['carrier-profile', 'Mi perfil']]); actions = accountMenu('RC', user.name, `Transportista · ${user.id} · ${user.status}`, data.session.hasClient ? 'Ir al panel Cliente' : 'Publicar como cliente', 'client');
    } else {
      nav = navButtons([['admin-reviews', 'Altas de transportistas'], ['admin-membership', 'Oferta de membresía']]); actions = accountMenu('AD', 'MiEnvio.es', 'Administrador', '', '');
    }
    $('#main-nav').innerHTML = nav; $('#header-actions').innerHTML = actions;
  }
  function accountMenu(initials, name, meta, switchLabel, switchContext) {
    const switchAction = switchLabel ? `<button type="button" data-action="switch-context" data-context="${switchContext}">${switchLabel}</button>` : '';
    return `<details class="account-menu"><summary class="account-chip"><span>${initials}</span><span><small>${escapeHtml(meta)}</small>${escapeHtml(name)}</span><span class="account-chevron" aria-hidden="true">⌄</span></summary><div class="account-menu-panel">${switchAction}<button type="button" data-action="logout">Cerrar sesión</button></div></details>`;
  }
  function navButtons(items) { return items.map(([route, label]) => `<button type="button" data-route="${route}" class="${data.route === route ? 'is-current' : ''}">${label}</button>`).join(''); }
  function pageHeading(eyebrow, title, description = '', actions = '') { return `<section class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${description ? `<p>${description}</p>` : ''}</div>${actions ? `<div class="page-actions">${actions}</div>` : ''}</section>`; }
  function examplePlaceholders(markup) { return markup.replace(/placeholder="(?=[^"])(?!Ej\.)/g, 'placeholder="Ej. '); }
  function viewShell(content, className = '') { return `<div class="shell workspace ${className}">${examplePlaceholders(content)}</div>`; }
  function callout(title, text, tone = 'info', actions = '') { return `<div class="callout callout-${tone}"><span class="callout-icon" aria-hidden="true">${tone === 'warning' || tone === 'danger' ? '!' : tone === 'success' ? '✓' : 'i'}</span><div><strong>${title}</strong><p>${text}</p>${actions}</div></div>`; }
  function emptyState(title, text, action = '') { return `<div class="empty-state"><span aria-hidden="true">○</span><h2>${title}</h2><p>${text}</p>${action}</div>`; }

  function renderHome() {
    const carrier = data.audience === 'carrier';
    const steps = carrier ? [['1','Encuentra oportunidades','Filtra por ruta, categoría y fecha.'],['2','Aclara y presupuesta','Pregunta y presenta una o varias opciones.'],['3','Consigue el servicio','Contacta cuando el cliente acepte.']] : [['1','Describe tu envío','Origen, destino, fechas y medidas.'],['2','Compara presupuestos','Precio y condiciones, sin datos de contacto.'],['3','Elige y contacta','Coordina directamente con el transportista.']];
    return `<section class="hero shell"><div class="hero-copy"><p class="eyebrow">${carrier ? 'Para empresas y autónomos' : 'Transporte dentro de España'}</p><h1>${carrier ? 'Más rutas. Menos kilómetros en vacío.' : 'Tu envío, en buenas manos.'}</h1><p class="hero-lead">${carrier ? 'Encuentra transportes compatibles con tus rutas, consulta los presupuestos existentes y presenta tus propias propuestas cuando tu alta esté aprobada y tu membresía habilitada.' : 'Publica lo que necesitas transportar, recibe presupuestos y elige con calma. Tus datos de contacto se comparten solo cuando aceptas una propuesta.'}</p><div class="hero-actions"><button class="button button-primary button-large" type="button" data-action="primary">${carrier ? 'Buscar anuncios' : 'Publicar anuncio'}</button></div><div class="trust-row">${(carrier ? ['Oportunidades en toda España', 'Varios presupuestos por anuncio', 'Primer mes gratuito'] : ['Sin coste para clientes', 'Compara antes de elegir', 'Contacto tras aceptar']).map((item) => `<span>${item}</span>`).join('')}</div></div><div class="route-card" aria-label="Ejemplo de transporte"><div class="route-card-top"><span class="category-icon" aria-hidden="true">▣</span><div><small>Muebles</small><strong>Mesa de comedor y 6 sillas</strong></div>${status('Activo')}</div><div class="route-line"><div><span class="route-dot origin"></span><small>Origen</small><strong>28013 Madrid</strong></div><div class="route-track"></div><div><span class="route-dot destination"></span><small>Destino</small><strong>46001 Valencia</strong></div></div><div class="quote-preview"><div><span>3</span> presupuestos activos</div><strong>desde 295 €</strong></div></div></section><section class="steps-strip"><div class="shell steps">${steps.map((step) => `<article><span>${step[0]}</span><div><strong>${step[1]}</strong><p>${step[2]}</p></div></article>`).join('')}</div></section>`;
  }
