    return viewShell(`<div class="auth-layout"><section class="auth-copy"><p class="eyebrow">Acceso único</p><h1>Entra o regístrate en MiEnvio.es.</h1><p>La misma cuenta permite usar un perfil cliente, un perfil transportista o ambos.</p>${['Escribe tu email para identificar tu cuenta.','Si ya existe, te pediremos la contraseña.','Si es nuevo, completarás el perfil que has elegido.'].map((text, i) => `<div class="mini-feature"><span>${i + 1}</span><p>${text}</p></div>`).join('')}</section><section class="panel auth-panel"><h2>Entrar o registrarse</h2><p class="context-note">Continuarás en el área de <strong>${role}</strong></p><button class="button button-google" type="button" data-action="google-login">G <span>Continuar con Google</span></button><div class="divider"><span>o con correo electrónico</span></div>${form}${passwordStep ? '<p class="form-note">Contraseña simulada: <strong>Demo1234!</strong></p>' : ''}</section></div>`, 'auth-page');
